rows.old_statement_tex:
\label{thm:intro-low-dimensional}
Let \(1\leq \d\leq10\).  Every real \(u\in H^{\d/2}(\T^\d)\) satisfies
\begin{equation}
 \log\int_{\T^\d}e^{u-\bar u}\,\dd\muunif
 \leq\frac{1}{4\d c_\d}\Ebo_\d(u).
 \label{eq:intro-low-primal}
\end{equation}
Equivalently, every probability density of finite entropy satisfies
\begin{equation}
 \Hr(\rho\mid\muunif)\geq \d\Gc_\d(\rho).
 \label{eq:intro-low-dual}
\end{equation}
The coefficient in \eqref{eq:intro-low-primal} is sharp.  In dimension one, equality is attained precisely by the family \eqref{eq:intro-circle-extremizers}, up to additive constants, equivalently by the Poisson kernels \eqref{eq:intro-circle-poisson}.  In dimensions two through ten, equality holds only for constants, equivalently only for \(\rho\equiv1\).

rows.paper2_statement_tex:
\label{thm:intro-low-dimensional}
Let \(1\leq\d\leq10\). We have
\begin{equation}
 \log\int_{\T^\d}e^{u-\bar u}\,\dd\muunif
 \leq\frac{1}{4\d c_\d}\norm{u}_{\dot H^{\d/2}}^2,
 \qquad \forall u\in H^{\d/2}(\T^\d).
 \label{eq:intro-low-primal}
\end{equation}
Equivalently,
\begin{equation}
 \Ent(\rho)\geq \d c_\d\norm{\rho}_{\dot H^{-\d/2}}^2,
 \qquad \forall \rho\in\mathcal P_{\mathrm{ac}}(\T^\d).
 \label{eq:intro-low-dual}
\end{equation}
The coefficient in \eqref{eq:intro-low-primal} is sharp. Density equality statements are understood for densities with finite entropy. For \(\d=1\), equality is attained precisely by the family \eqref{eq:intro-circle-extremizers}, up to additive constants, equivalently by the Poisson kernels \eqref{eq:intro-circle-poisson}. For \(2\leq\d\leq10\), equality holds only for constants, equivalently only for \(\rho\equiv1\).

rows.old_statement_tex:
\label{thm:intro-d11}
Let
\begin{equation}
 \rho_*(x)
 :=\sum_{n\in\Z^{11}}
 5^{11}\frac{122880}{\pi^6}
 \bigl(1+25|x+n|^2\bigr)^{-11}.
 \label{eq:intro-rho-star}
\end{equation}
Then \(\rho_*\) is a smooth positive probability density on \(\T^{11}\), and
\begin{equation}
 \Hr(\rho_*\mid\muunif)<\frac{8653}{600},
 \qquad
 \frac12\Qcal_{11}(\rho_*)>\frac{14475384292906}{10^{12}}.
 \label{eq:intro-d11-certificate}
\end{equation}
Consequently,
\begin{equation}
 \Cc_{11}\bigl(\As(11)\bigr)
 =\Pc_{11}\bigl(\betas(11)\bigr)>\frac1{30},
 \qquad
 17.715<\betagm(11)<20.630<\betas(11)<22.
 \label{eq:intro-d11-threshold}
\end{equation}
At \(\be=\betagm(11)\), the uniform density and at least one nonuniform smooth positive density are global minimizers of \(\Ec_{\be}\), while the Hessian at the uniform density is strictly positive.  Hence, \(\Pc_{11}\) has a corner at \(\betagm(11)\), and \(\Cc_{11}\) has a corresponding corner at \(\Azero(11)\).

