rows.old_statement_tex:
\label{lem:section2-finite-entropy-energy}
Let \(\mu\) be a probability measure on \(\T^{\d}\) such that \(\Hr(\mu\mid\muunif)<\infty\).  Then \(I_{\mu}>-\infty\).  More precisely, for every \(a\in(0,\d)\),
\begin{equation}
 0\leq-2I_{\mu}
 \leq\frac{2}{a}\Hr(\mu\mid\muunif)
 +\frac1a\log\iint_{(\T^{\d})^2}e^{a\g(x-y)}
 \,\dd\muunif(x)\dd\muunif(y).
 \label{eq:section2-finite-entropy-energy-bound}
\end{equation}
If \(P_t=e^{t\Delta}\) is the heat semigroup and \(\mu_t=P_t\mu\), then
\begin{align}
 \Hr(\mu_t\mid\muunif)&\longrightarrow\Hr(\mu\mid\muunif),
 \label{eq:section2-entropy-heat-approximation}\\
 I_{\mu_t}&\longrightarrow I_{\mu}
 \label{eq:section2-energy-heat-approximation}
\end{align}
when \(t\downarrow0\).  Moreover, \(\mu_t\) has a smooth strictly positive density for every \(t>0\).

rows.paper2_statement_tex:
\label{lem:section2-finite-entropy-energy}
Let $\mu=\rho\muunif$ be a probability measure on $\T^\d$ with $\Ent(\rho)<\infty$. Then $\norm{\rho}_{\dot H^{-\d/2}}<\infty$. More precisely, for every $a\in(0,\d)$,
\begin{equation}
 0\leq c_{\d}\norm{\rho}_{\dot H^{-\d/2}}^2
 \leq\frac{2}{a}\Ent(\rho)
 +\frac1a\log\iint_{(\T^{\d})^2}e^{a\g(x-y)}
 \,\dd\muunif(x)\dd\muunif(y).
 \label{eq:section2-finite-entropy-energy-bound}
\end{equation}
If $P_t=e^{t\Delta}$ is the heat semigroup, set $\rho_t:=P_t\rho$ and $\mu_t=\rho_t\muunif$. Then
\begin{align}
 \Ent(\rho_t)&\longrightarrow\Ent(\rho),
 \label{eq:section2-entropy-heat-approximation}\\
 \norm{\rho_t}_{\dot H^{-\d/2}}^2&\longrightarrow\norm{\rho}_{\dot H^{-\d/2}}^2
 \label{eq:section2-energy-heat-approximation}
\end{align}
when \(t\downarrow0\).  Moreover, \(\mu_t\) has a smooth strictly positive density for every \(t>0\).

rows.old_statement_tex:
\label{prop:section2-coefficient-pressure-duality}
Let \(A>0\) and set
\begin{equation}
 \be=\frac1{2Ac_{\d}}.
 \label{eq:section2-A-beta}
\end{equation}
Then
\begin{equation}
 \Cc_{\d}(A)=\Pc_{\d}(\be).
 \label{eq:section2-coefficient-pressure-duality}
\end{equation}
Both sides may take the value \(+\infty\).  The supremum defining \(\Pc_{\d}\) may be restricted to smooth strictly positive probability densities.

rows.paper2_statement_tex:
\label{prop:section2-coefficient-pressure-duality}
Let $A>0$ and set $\be:=(2Ac_\d)^{-1}$. Then
\begin{equation}
 \Cc_{\d}(A)=\Pc_{\d}(\be).
 \label{eq:section2-coefficient-pressure-duality}
\end{equation}
Both sides may take the value \(+\infty\). The supremum defining \(\Pc_{\d}\) may be restricted to smooth strictly positive probability densities.

rows.old_statement_tex:
\label{lem:section2-universal-obstructions}
The following statements hold.

\begin{enumerate}[(i)]
\item If \(\be>2\d\), then \(\Pc_{\d}(\be)=+\infty\).  Equivalently,
\begin{equation}
 \Cc_{\d}(A)=+\infty
 \qquad\text{when }A<\Acrit(\d).
 \label{eq:section2-subcritical-coefficient-infinite}
\end{equation}
At \(A=\Acrit(\d)\), the defect is finite by \eqref{eq:section2-critical-adams}.

\item If \(\be>\betas(\d)\), then \(\Pc_{\d}(\be)>0\).  Equivalently,
\begin{equation}
 \Cc_{\d}(A)>0
 \qquad\text{when }A<\As(\d).
 \label{eq:section2-below-spectral-positive}
\end{equation}
\end{enumerate}

\label{prop:section2-basic-curve-geometry}
The function \(\be\mapsto\Pc_{\d}(\be)\) is convex, nondecreasing, and nonnegative on \([0,2\d]\).  The function \(A\mapsto\Cc_{\d}(A)\) is convex, nonincreasing, and nonnegative on \((0,\infty)\).  Moreover,
\begin{equation}
 \betagm(\d)
 =\inf_{\substack{\mu\text{ probability},\ \mu\neq\muunif\\
 \Hr(\mu\mid\muunif)<\infty}}
 \frac{\Hr(\mu\mid\muunif)}{-I_{\mu}},
 \label{eq:section2-beta-gm-quotient}
\end{equation}
where \(-I_{\mu}>0\) for every nonuniform finite-entropy probability measure \(\mu\).  In particular,
\begin{align}
 \Pc_{\d}(\be)=0
 &\quad\Longleftrightarrow\quad 0\leq\be\leq\betagm(\d),
 \label{eq:section2-pressure-zero-set}\\
 \Cc_{\d}(A)=0
 &\quad\Longleftrightarrow\quad A\geq\Azero(\d),
 \label{eq:section2-defect-zero-set}
\end{align}
with
\begin{equation}
 \Azero(\d)=\frac1{2c_{\d}\betagm(\d)}.
 \label{eq:section2-A-zero}
\end{equation}
Finally,
\begin{equation}
 \betagm(\d)\leq\min\{\betac(\d),\betas(\d)\},
 \qquad
 \Azero(\d)\geq\max\{\Acrit(\d),\As(\d)\}.
 \label{eq:section2-threshold-upper-bounds}
\end{equation}

rows.paper2_statement_tex:
\label{prop:section2-basic-curve-geometry}
The function \(\be\mapsto\Pc_{\d}(\be)\) is convex, nondecreasing, and nonnegative on \([0,2\d]\).  The function \(A\mapsto\Cc_{\d}(A)\) is convex, nonincreasing, and nonnegative on \((0,\infty)\).  Moreover,
\begin{equation}
 \betagm(\d)
 =\inf_{\substack{\rho\in\mathcal P_{\mathrm{ac}}(\T^\d)\\
 0<\Ent(\rho)<\infty}}
 \frac{2\Ent(\rho)}{c_\d\norm{\rho}_{\dot H^{-\d/2}}^2}.
 \label{eq:section2-beta-gm-quotient}
\end{equation}
In particular,
\begin{align}
 \Pc_{\d}(\be)=0
 &\quad\Longleftrightarrow\quad 0\leq\be\leq\betagm(\d),
 \label{eq:section2-pressure-zero-set}\\
 \Cc_{\d}(A)=0
 &\quad\Longleftrightarrow\quad A\geq\Azero(\d),
 \label{eq:section2-defect-zero-set}
\end{align}
where $\Azero(\d)$ is as in \eqref{eq:intro-A-landmarks}.
Finally,
\begin{equation}
 \betagm(\d)\leq\min\{\betac(\d),\betas(\d)\},
 \qquad
 \Azero(\d)\geq\max\{\Acrit(\d),\As(\d)\}.
 \label{eq:section2-threshold-upper-bounds}
\end{equation}

rows.old_statement_tex:
\label{prop:section2-gap-identities}
Let \(A>0\), let \(\be=(2Ac_{\d})^{-1}\), and define \(\mu_u\) and \(u_{\mu}\) by \eqref{eq:section2-gibbs-density} and \eqref{eq:section2-potential-of-density}.  Then every real mean-zero \(u\in H^{\d/2}(\T^{\d})\) satisfies
\begin{align}
 \log\int e^u\,\dd\muunif-A\Ebo_{\d}(u)
 &=-\be I_{\mu_u}-\Hr(\mu_u\mid\muunif)
 -A\Ebo_{\d}(u-u_{\mu_u}).
 \label{eq:section2-primal-gap-identity}
\end{align}
Every finite-entropy probability measure \(\mu\) satisfies
\begin{align}
 -\be I_{\mu}-\Hr(\mu\mid\muunif)
 &=\log\int e^{u_{\mu}}\,\dd\muunif
 -A\Ebo_{\d}(u_{\mu})
 -\Hr(\mu\mid\mu_{u_{\mu}}).
 \label{eq:section2-dual-gap-identity}
\end{align}

rows.paper2_statement_tex:
\label{prop:section2-gap-identities}
Let \(A>0\), let \(\be=(2Ac_{\d})^{-1}\), and define \(\rho_u\) and \(u_{\rho}\) by \eqref{eq:section2-gibbs-density} and \eqref{eq:section2-potential-of-density}.  Then every real mean-zero \(u\in H^{\d/2}(\T^{\d})\) satisfies
\begin{align}
 \log\int e^u\,\dd\muunif-A\norm{u}_{\dot H^{\d/2}}^2
 &=\frac{\be c_{\d}}2\norm{\rho_u}_{\dot H^{-\d/2}}^2-\Ent(\rho_u)
 -A\norm{u-u_{\rho_u}}_{\dot H^{\d/2}}^2.
 \label{eq:section2-primal-gap-identity}
\end{align}
Every $\rho\in\mathcal P_{\mathrm{ac}}(\T^\d)$ with $\Ent(\rho)<\infty$ satisfies
\begin{align}
 \frac{\be c_{\d}}2\norm{\rho}_{\dot H^{-\d/2}}^2-\Ent(\rho)
 &=\log\int e^{u_{\rho}}\,\dd\muunif
 -A\norm{u_{\rho}}_{\dot H^{\d/2}}^2
 -\Hr(\rho\mid\rho_{u_\rho}).
 \label{eq:section2-dual-gap-identity}
\end{align}

rows.old_statement_tex:
\label{cor:section2-extremizer-correspondence}
Let \(A>0\) and \(\be=(2Ac_{\d})^{-1}\).

\begin{enumerate}[(i)]
\item A real mean-zero potential \(u\) maximizes \(\Cc_{\d}(A)\) if and only if \(\mu_u\) maximizes \(\Pc_{\d}(\be)\) and
\begin{equation}
 u=\be\,\g*(\mu_u-\muunif).
 \label{eq:section2-primal-critical-relation}
\end{equation}

\item A finite-entropy probability measure \(\mu\) maximizes \(\Pc_{\d}(\be)\) if and only if \(u_{\mu}\) maximizes \(\Cc_{\d}(A)\) and
\begin{equation}
 \frac{\dd\mu}{\dd\muunif}
 =\frac{e^{u_{\mu}}}{\int e^{u_{\mu}}\,\dd\muunif}.
 \label{eq:section2-dual-critical-relation}
\end{equation}

\item Every extremizing measure has a smooth strictly positive density \(\rho\).  Every extremizing pair \((u,\mu)\), with \(\mu=\rho\muunif\), solves
\begin{equation}
 \frac1{c_{\d}}|\nabla|^{\d}u
 =\be(\rho-1),
 \qquad
 \rho=\frac{e^u}{\int e^u\,\dd\muunif}.
 \label{eq:section2-euler-lagrange}
\end{equation}
Equivalently,
\begin{equation}
 \rho
 =\frac{\exp\{\be\,\g*(\rho-1)\}}
 {\int\exp\{\be\,\g*(\rho-1)\}\,\dd\muunif}.
 \label{eq:section2-kirkwood-monroe}
\end{equation}
\end{enumerate}

rows.paper2_statement_tex:
\label{cor:section2-extremizer-correspondence}
Let \(A>0\) and \(\be=(2Ac_{\d})^{-1}\).

\begin{enumerate}[(i)]
\item A real mean-zero potential \(u\) maximizes \(\Cc_{\d}(A)\) if and only if \(\rho_u\) maximizes \(\Pc_{\d}(\be)\) and
\begin{equation}
 u=\be\,\g*\rho_u.
 \label{eq:section2-primal-critical-relation}
\end{equation}

\item A density $\rho\in\mathcal P_{\mathrm{ac}}(\T^\d)$ with $\Ent(\rho)<\infty$ maximizes \(\Pc_{\d}(\be)\) if and only if \(u_{\rho}\) maximizes \(\Cc_{\d}(A)\) and
\begin{equation}
 \rho
 =\frac{e^{u_{\rho}}}{\int e^{u_{\rho}}\,\dd\muunif}.
 \label{eq:section2-dual-critical-relation}
\end{equation}

\item Every extremizing density \(\rho\) is smooth and strictly positive. Every extremizing pair \((u,\rho)\) solves
\begin{equation}
 |\nabla|^{\d}u
 =\be c_{\d}(\rho-1),
 \qquad
 \rho=\frac{e^u}{\int e^u\,\dd\muunif}.
 \label{eq:section2-euler-lagrange}
\end{equation}
Equivalently,
\begin{equation}
 \rho
 =\frac{\exp\{\be\,\g*(\rho-1)\}}
 {\int\exp\{\be\,\g*(\rho-1)\}\,\dd\muunif}.
 \label{eq:section2-kirkwood-monroe}
\end{equation}
\end{enumerate}

rows.old_statement_tex:
\label{prop:section2-subcritical-attainment}
Let \(0<\be<2\d\) and put \(A=(2\be c_{\d})^{-1}>\Acrit(\d)\).  Then the supremum defining \(\Cc_{\d}(A)\) is attained by a real mean-zero potential \(u\in H^{\d/2}(\T^{\d})\), and the supremum defining \(\Pc_{\d}(\be)\) is attained by a probability measure \(\mu\).  Every such extremizing measure has a smooth strictly positive density \(\rho\), and
\begin{equation}
 0<\rho\in C^\infty(\T^{\d}),
 \qquad
 u\in C^\infty(\T^{\d}).
 \label{eq:section2-subcritical-smoothness}
\end{equation}
The same conclusion holds at \(\be=2\d\) whenever the endpoint supremum is attained.

rows.paper2_statement_tex:
\label{prop:section2-subcritical-attainment}
Let \(0<\be<2\d\) and put \(A=(2\be c_{\d})^{-1}>\Acrit(\d)\).  Then the supremum defining \(\Cc_{\d}(A)\) is attained by a real mean-zero potential \(u\in H^{\d/2}(\T^{\d})\), and the supremum defining \(\Pc_{\d}(\be)\) is attained by a probability density \(\rho\). Every such extremizing density is smooth and strictly positive, and
\begin{equation}
 0<\rho\in C^\infty(\T^{\d}),
 \qquad
 u\in C^\infty(\T^{\d}).
 \label{eq:section2-subcritical-smoothness}
\end{equation}
The same conclusion holds at \(\be=2\d\) whenever the endpoint supremum is attained.

rows.old_statement_tex:
\label{lem:fractional}

Let $u(\theta)=U(\cos\theta_1,\ldots,\cos\theta_\d)$ with $U\in C^\infty([-1,1]^\d)$. For a nonzero multi-index $\alpha$, set

\begin{equation}
 S_\alpha=\{i:\alpha_i>0\},\quad
 \Omega_\alpha=(0,\pi)^{S_\alpha}\times(\R/2\pi\Z)^{S_\alpha^c},\quad
 w_\alpha=\prod_{i\in S_\alpha}\sin^{\alpha_i}\theta_i.
\end{equation}

Thus the superscripts in the Cartesian product record the original coordinate labels: $\theta_i\in(0,\pi)$ when $i\in S_\alpha$, and $\theta_i\in\R/2\pi\Z$ when $i\in S_\alpha^c$.

All restricted operators use Lebesgue measure, with the same normalization before and after restriction. Let $B_\alpha$ be the Friedrichs operator\footnote{This is the self-adjoint operator associated with the closure of the indicated nonnegative quadratic form; see \cite[Section~2.3, Theorems~2.13--2.14]{Teschl2014}.}

\begin{equation}
 B_\alpha=P_{D_{S_\alpha}}+V_\alpha,\qquad
 V_\alpha=\sum_{i:\alpha_i>0}\alpha_i(\alpha_i-1)\csc^2\theta_i.
 \label{eq:restricted-jacobi-operator}
\end{equation}

Here $P_{D_{S_\alpha}}$ is the second-order Laplacian $-\Delta_\theta$ on $\Omega_\alpha$, with zero Dirichlet values at $\theta_i=0,\pi$ when $\alpha_i>0$, and periodic conditions when $\alpha_i=0$. By contrast, $P=-\Delta_\theta$ acts on the full angular torus, and $P^s$ denotes its spectral power:

\begin{equation}
 \widehat{P^su}(k)=|k|^{2s}\widehat u(k),\qquad k\in\Z^\d.
 \label{eq:angular-periodic-power}
\end{equation}

For every $s>0$, $w_\alpha\partial_z^\alpha U\in\Dom(B_\alpha^s)$, and

\begin{equation}
 B_\alpha^s(w_\alpha\partial_z^\alpha U)
  =w_\alpha\partial_z^\alpha(P^su).
 \label{eq:fractional-intertwining}
\end{equation}

The derivative on the right is taken after expressing the smooth even function $P^su$ in the cosine variables.

rows.paper2_statement_tex:
\label{lem:fractional}

Let $u(x)=U(\cos(2\pi x_1),\ldots,\cos(2\pi x_\d))$ with $U\in C^\infty([-1,1]^\d)$. For a nonzero multi-index $\alpha$, set

\begin{equation}
 S_\alpha=\{i:\alpha_i>0\},\quad
 \Omega_\alpha=(0,1/2)^{S_\alpha}\times(\R/\Z)^{S_\alpha^c},\quad
 w_\alpha=\prod_{i\in S_\alpha}\sin^{\alpha_i}(2\pi x_i).
\end{equation}

Thus the superscripts in the Cartesian product record the original coordinate labels: $x_i\in(0,1/2)$ when $i\in S_\alpha$, and $x_i\in\R/\Z$ when $i\in S_\alpha^c$.

All restricted operators use Lebesgue measure, with the same normalization before and after restriction. Let $B_\alpha$ be the Friedrichs operator\footnote{This is the self-adjoint operator associated with the closure of the indicated nonnegative quadratic form; see \cite[Section~2.3, Theorems~2.13--2.14]{Teschl2014}.}

\begin{equation}
 B_\alpha=P_{D_{S_\alpha}}+V_\alpha,\qquad
 V_\alpha=(2\pi)^2\sum_{i:\alpha_i>0}\alpha_i(\alpha_i-1)\csc^2(2\pi x_i).
 \label{eq:restricted-jacobi-operator}
\end{equation}

Here $P_{D_{S_\alpha}}$ is the second-order Laplacian $-\Delta$ on $\Omega_\alpha$, with zero Dirichlet values at $x_i=0,1/2$ when $\alpha_i>0$, and periodic conditions when $\alpha_i=0$. By contrast, $|\nabla|^2=-\Delta$ acts on the full unit-period torus, and its spectral powers satisfy

\begin{equation}
 \widehat{|\nabla|^{2s}u}(k)=(2\pi|k|)^{2s}\widehat u(k),\qquad k\in\Z^\d.
 \label{eq:angular-periodic-power}
\end{equation}

For every $s>0$, $w_\alpha\partial_z^\alpha U\in\Dom(B_\alpha^s)$, and

\begin{equation}
 B_\alpha^s(w_\alpha\partial_z^\alpha U)
  =w_\alpha\partial_z^\alpha(|\nabla|^{2s}u).
 \label{eq:fractional-intertwining}
\end{equation}

The derivative on the right is taken after expressing the smooth even function $|\nabla|^{2s}u$ in the cosine variables.

